<script lang="ts">
  const VALID_STATES = ['novo', 'bom', 'marcas_de_uso', 'danificado', 'manutencao', 'baixado'];
  let { onClose, onSaved }: { onClose: () => void; onSaved: (item: Record<string, unknown>) => void } = $props();
  let form = $state({ marca: '', modelo: '', numeroSerie: '', tipo: 'headset', conexao: '', microfone: false, estado: 'bom', observacoes: '' }); let erro = $state(''); let salvando = $state(false);
  async function salvar() { if (!form.marca.trim() || !form.modelo.trim() || !form.conexao.trim()) { erro = 'Preencha os campos obrigatórios.'; return; } salvando = true; try { const response = await fetch('/api/equipamentos/fone', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); if (response.status === 401) { window.location.assign('/login'); return; } if (!response.ok) { erro = 'Não foi possível cadastrar o fone.'; return; } onSaved(await response.json()); } catch { erro = 'Não foi possível cadastrar o fone. Tente novamente.'; } finally { salvando = false; } }
</script>
<div class="modal edit-person-modal" role="presentation" onclick={(event) => event.target === event.currentTarget && !salvando && onClose()}><div class="modal__content edit-person-dialog card panel" role="dialog" aria-modal="true" aria-labelledby="headset-title"><div class="edit-person-heading"><h2 id="headset-title">Adicionar fone</h2><button class="button--secondary edit-person-close" type="button" onclick={onClose}>×</button></div><form onsubmit={(event) => { event.preventDefault(); salvar(); }}><div class="form-grid"><div class="form-group"><label for="headset-marca">Marca</label><input id="headset-marca" bind:value={form.marca} /></div><div class="form-group"><label for="headset-modelo">Modelo</label><input id="headset-modelo" bind:value={form.modelo} /></div><div class="form-group"><label for="headset-serie">Número de série</label><input id="headset-serie" bind:value={form.numeroSerie} /></div><div class="form-group"><label for="headset-tipo">Tipo</label><select id="headset-tipo" bind:value={form.tipo}><option>headset</option><option>intra</option><option>over-ear</option></select></div><div class="form-group"><label for="headset-conexao">Conexão</label><input id="headset-conexao" bind:value={form.conexao} /></div><label class="toggle" for="headset-microfone"><input id="headset-microfone" type="checkbox" bind:checked={form.microfone} /><span class="toggle__track"></span>Microfone</label><div class="form-group"><label for="headset-estado">Estado</label><select id="headset-estado" bind:value={form.estado}>{#each VALID_STATES as state}<option value={state}>{state}</option>{/each}</select></div><div class="form-group"><label for="headset-observacoes">Observações</label><textarea id="headset-observacoes" bind:value={form.observacoes}></textarea></div></div>{#if erro}<p class="form-error" role="alert">{erro}</p>{/if}<footer class="form-actions edit-person-actions"><button class="button--secondary" type="button" onclick={onClose}>Cancelar</button><button class="button--primary" type="submit" disabled={salvando}>Salvar</button></footer></form></div></div>
